def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r-r0, c-c0) for r, c in points}
    dh = max(r for r, c in shape)
    dw = max(c for r, c in shape)
    out = [row[:] for row in grid]
    for r in range(h-dh):
        for c in range(w-dw):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(grid[rr][cc] == 0 for rr, cc in cells):
                for rr, cc in cells:
                    out[rr][cc] = color
    return out
